import{_ as r,a0 as l,w as d,s as m,ao as p,I as o,x as s,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"systemd 与 sysVinit 彩版对照表 | LCTT x X-CMD","titleTemplate":false,"description":"systemd 与 sysVinit 彩版对照表 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"systemd 与 sysVinit 彩版对照表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"systemd 与 sysVinit 彩版对照表 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140910 Colourful systemd vs sysVinit Linux Cheatsheet","title":"systemd 与 sysVinit 彩版对照表","tag":"201409","desc":""},"relativePath":"201409/20140910 Colourful systemd vs sysVinit Linux Cheatsheet.md","filePath":"[post].md"}'),a={name:"201409/20140910 Colourful systemd vs sysVinit Linux Cheatsheet.md"};function u(y,t,f,x,C,g){const e=l("Link");return d(),m("div",null,[t[18]||(t[18]=p('<h1 id="systemd-与-sysvinit-彩版对照表" tabindex="-1">systemd 与 sysVinit 彩版对照表 <a class="header-anchor" href="#systemd-与-sysvinit-彩版对照表" aria-label="Permalink to “systemd 与 sysVinit 彩版对照表”">​</a></h1><p><strong>systemd</strong> 是一种新型init系统「译者注：每个操作系统都有一个启动程序，而Linux init是Linux系统操作中不可缺少的程序之一。所谓的init进程，它是一个由内核启动的用户级进程。内核自行启动（已经被载入内存，开始运行，并已初始化所有的设备驱动程序和数据结构等）之后，就通过启动一个用户级程序init的方式，完成引导进程。所以init始终是第一个进程（其进程编号始终为1）」，最早在Fedora中使用「译者注：真的吗？不是Arch？」，经过调整适应了其它许多发行版，例如RedHat、Suse和CentOS。</p><p>历史上，我们大部分人用过传统的SysV init 初始化脚本，它通常情况下在/etc/rc.d/init.d/文件夹下。这些脚本调用守护进程二进制代码，在后台fork一个进程。</p><p>尽管shell脚本非常的灵活，但是很难实现像superviseing（监管）进程和并行执行命令这样的任务。</p><p>通过对systemd的新式守护进程的介绍，我们发现systemd可以在runtime（运行时）更加简单的监管和控制守护进程，并且简化了监控的实现方式（implementation）。</p><p><strong>systemctl</strong>命令是systemd团队一个非常好的首创。</p><p>这个命令能够显示更多的详细错误信息和包括启动错误在内的服务运行时错误。systemd引入了一个新术语：<strong>cgroups</strong>（控制组），它基本上是可被分层次安排的进程任务组。「译者注：这里简单介绍一下cgroup（control group）称为Containers，Containers着眼于资源的分配，利用configfs作配置。它有两个重要概念：第一是subsystem，内核可以给进程提供的服务/资源；第二是container，一个进程组，成员共享同样的一个或多个子系统分配限制。Containers是分层次的，一个container可以hold多个container。它的可取之处是创建了一个资源分配的框架，其它开发者可以利用这个框架去开发自己的资源分配patch，比如磁盘设备。」</p><p>如果仅仅通过原来的初始化系统，决定哪个进程是做什么的、属于哪个用户的变得越来越困难。</p><p>但是通过systemd，当一个进程派生其它进程时，这些子进程会被自动变成父进程控制组的成员，这样一来就可以避免继承的混乱。</p><p><img src="http://images.linoxide.com/systemd-vs-sysVinit-cheatsheet.jpg" alt=""></p>',10)),o("p",null,[t[2]||(t[2]=s("有许多新的运行",-1)),i(e,{href:"http://linoxide.com/linux-command/linux-systemd-commands/"},{default:n(()=>[...t[0]||(t[0]=[s("在 rhel / centos 7.0 上的 systemd 命令",-1)])]),_:1}),t[3]||(t[3]=s("可以替代 sysvinit 的对应命令。你也可以下载 ",-1)),i(e,{href:"http://images.linoxide.com/systemd-vs-sysVinit-cheatsheet.pdf"},{default:n(()=>[...t[1]||(t[1]=[s("本文的 PDF 版本",-1)])]),_:1}),t[4]||(t[4]=s("。",-1))]),t[19]||(t[19]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=s("via: ",-1)),i(e,{href:"http://linoxide.com/linux-command/systemd-vs-sysvinit-cheatsheet/"},{default:n(()=>[...t[5]||(t[5]=[s("http://linoxide.com/linux-command/systemd-vs-sysvinit-cheatsheet/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("作者：",-1)),i(e,{href:"http://linoxide.com/author/bobbin/"},{default:n(()=>[...t[7]||(t[7]=[s("Bobbin Zachariah",-1)])]),_:1}),t[11]||(t[11]=s(" 译者：",-1)),i(e,{href:"https://github.com/szrlee"},{default:n(()=>[...t[8]||(t[8]=[s("szrlee",-1)])]),_:1}),t[12]||(t[12]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原创翻译，",-1)),i(e,{href:"http://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[s("Linux中国",-1)])]),_:1}),t[17]||(t[17]=s(" 荣誉推出",-1))])])}const h=r(a,[["render",u]]);export{v as __pageData,h as default};
